export interface ConnectorConfig {
  /** Full Discord webhook URL (e.g., https://discord.com/api/webhooks/123/abc) */
  discordWebhookUrl?: string
  /** Discord webhook ID (used with discordWebhookToken to build the URL) */
  discordWebhookId?: string
  /** Discord webhook token (used with discordWebhookId to build the URL) */
  discordWebhookToken?: string
  /** Optional fetch implementation for testing or customization */
  fetch?: typeof fetch
}

export interface AirtableWebhookPayload {
  id: string
  fields: Record<string, unknown>
  createdTime: string
}

export interface DiscordWebhookResponse {
  id: string
  type: number
  content: string
  channel_id: string
  author: {
    username: string
    discriminator: string
    id: string
    avatar: string | null
  }
}

export interface HandleResult {
  discordMessageId: string
  discordChannelId: string
}

function buildDiscordWebhookUrl(config: ConnectorConfig): string {
  if (config.discordWebhookUrl) {
    return config.discordWebhookUrl
  }
  if (config.discordWebhookId && config.discordWebhookToken) {
    return `https://discord.com/api/webhooks/${config.discordWebhookId}/${config.discordWebhookToken}`
  }
  throw new Error('Discord webhook URL not configured: provide discordWebhookUrl or both discordWebhookId and discordWebhookToken')
}

function formatMessageContent(payload: AirtableWebhookPayload): string {
  const fieldEntries = Object.entries(payload.fields)
  const fieldsString = fieldEntries.length > 0
    ? fieldEntries.map(([key, value]) => `${key}: ${String(value)}`).join(', ')
    : 'no fields'
  return `New Airtable row: ${payload.id} - ${fieldsString}, Created: ${payload.createdTime}`
}

function validatePayload(payload: unknown): asserts payload is AirtableWebhookPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Invalid payload: expected an object')
  }
  const p = payload as Record<string, unknown>
  if (typeof p.id !== 'string' || p.id.trim() === '') {
    throw new Error('Missing required field: id (string)')
  }
  if (!p.fields || typeof p.fields !== 'object' || Array.isArray(p.fields)) {
    throw new Error('Missing required field: fields (object)')
  }
  if (typeof p.createdTime !== 'string' || p.createdTime.trim() === '') {
    throw new Error('Missing required field: createdTime (string)')
  }
}

export async function handle(payload: unknown, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)
  const airtablePayload = payload as AirtableWebhookPayload

  const content = formatMessageContent(airtablePayload)
  if (content.length > 2000) {
    throw new Error(`Message content exceeds Discord's 2000 character limit (got ${content.length})`)
  }

  const webhookUrl = buildDiscordWebhookUrl(config)
  const fetchImpl = config.fetch ?? fetch

  const response = await fetchImpl(webhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({ content }),
  })

  if (!response.ok) {
    throw new Error(`Discord webhook request failed: ${response.status} ${response.statusText} for POST ${webhookUrl}`)
  }

  const data = (await response.json()) as DiscordWebhookResponse
  return {
    discordMessageId: data.id,
    discordChannelId: data.channel_id,
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, AirtableWebhookPayload } from './connector'
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse, TARGET_ENDPOINTS } from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/123456789012345678/abcdefghijklmnopqrstuvwxyz',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as AirtableWebhookPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.discordMessageId).toBe('123456789012345678')
    expect(result.discordChannelId).toBe('987654321098765432')
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://discord.com/api/webhooks/123456789012345678/abcdefghijklmnopqrstuvwxyz')
    expect(calls[0].json).toEqual({
      content: 'New Airtable row: rec123abc - Name: John Doe, Email: john@example.com, Created: 2024-01-15T10:30:00.000Z',
    })
  })
})

describe('handle', () => {
  it('sends formatted message to Discord webhook on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://discord.com/api/webhooks/WEBHOOK_ID/WEBHOOK_TOKEN'
        ? jsonResponse({
            id: '999888777666555444',
            type: 1,
            content: 'New Airtable row: recTest - Name: Test User, Email: test@example.com, Created: 2024-06-01T12:00:00.000Z',
            channel_id: '111222333444555666',
            author: { username: 'Webhook', discriminator: '0001', id: '111222333444555666', avatar: null },
          }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: AirtableWebhookPayload = {
      id: 'recTest',
      fields: { Name: 'Test User', Email: 'test@example.com' },
      createdTime: '2024-06-01T12:00:00.000Z',
    }

    const config: ConnectorConfig = {
      discordWebhookId: 'WEBHOOK_ID',
      discordWebhookToken: 'WEBHOOK_TOKEN',
      fetch,
    }

    const result = await handle(payload, config)

    expect(result.discordMessageId).toBe('999888777666555444')
    expect(result.discordChannelId).toBe('111222333444555666')
    expect(calls.length).toBe(1)
    expect(calls[0].method).toBe('POST')
    expect(calls[0].json).toEqual({
      content: 'New Airtable row: recTest - Name: Test User, Email: test@example.com, Created: 2024-06-01T12:00:00.000Z',
    })
  })

  it('uses full webhook URL when provided', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://discord.com/api/webhooks/FULL_URL_ID/FULL_URL_TOKEN'
        ? jsonResponse({
            id: 'msg123',
            type: 1,
            content: 'test',
            channel_id: 'chan123',
            author: { username: 'Webhook', discriminator: '0001', id: 'chan123', avatar: null },
          }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: AirtableWebhookPayload = {
      id: 'rec1',
      fields: { Foo: 'bar' },
      createdTime: '2024-01-01T00:00:00.000Z',
    }

    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/FULL_URL_ID/FULL_URL_TOKEN',
      fetch,
    }

    await handle(payload, config)
    expect(calls[0].url).toBe('https://discord.com/api/webhooks/FULL_URL_ID/FULL_URL_TOKEN')
  })

  it('throws when required field id is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { fields: { Name: 'Test' }, createdTime: '2024-01-01T00:00:00.000Z' }
    const config: ConnectorConfig = { discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch }

    await expect(handle(payload as unknown as AirtableWebhookPayload, config)).rejects.toThrow('Missing required field: id')
  })

  it('throws when required field fields is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { id: 'rec1', createdTime: '2024-01-01T00:00:00.000Z' }
    const config: ConnectorConfig = { discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch }

    await expect(handle(payload as unknown as AirtableWebhookPayload, config)).rejects.toThrow('Missing required field: fields')
  })

  it('throws when required field createdTime is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload = { id: 'rec1', fields: { Name: 'Test' } }
    const config: ConnectorConfig = { discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch }

    await expect(handle(payload as unknown as AirtableWebhookPayload, config)).rejects.toThrow('Missing required field: createdTime')
  })

  it('throws when payload is not an object', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const config: ConnectorConfig = { discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch }

    await expect(handle(null as unknown, config)).rejects.toThrow('Invalid payload: expected an object')
    await expect(handle('string' as unknown, config)).rejects.toThrow('Invalid payload: expected an object')
  })

  it('throws on non-2xx response from Discord', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ message: 'Invalid Webhook Token' }, 401))

    const payload: AirtableWebhookPayload = {
      id: 'rec1',
      fields: { Name: 'Test' },
      createdTime: '2024-01-01T00:00:00.000Z',
    }

    const config: ConnectorConfig = {
      discordWebhookUrl: 'https://discord.com/api/webhooks/1/2',
      fetch,
    }

    await expect(handle(payload, config)).rejects.toThrow('Discord webhook request failed: 401 Unauthorized for POST https://discord.com/api/webhooks/1/2')
    expect(calls.length).toBe(1)
  })

  it('throws when message content exceeds 2000 characters', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const longFieldValue = 'x'.repeat(2000)
    const payload: AirtableWebhookPayload = {
      id: 'rec1',
      fields: { Description: longFieldValue },
      createdTime: '2024-01-01T00:00:00.000Z',
    }
    const config: ConnectorConfig = { discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch }

    await expect(handle(payload, config)).rejects.toThrow("exceeds Discord's 2000 character limit")
  })

  it('throws when neither webhook URL nor id/token provided', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))
    const payload: AirtableWebhookPayload = {
      id: 'rec1',
      fields: { Name: 'Test' },
      createdTime: '2024-01-01T00:00:00.000Z',
    }
    const config: ConnectorConfig = { fetch }

    await expect(handle(payload, config)).rejects.toThrow('Discord webhook URL not configured')
  })
})

// Written by patchbay from the API documentation. Regenerated on every attempt, do not edit.
// Source: https://support.airtable.com/articles/6618712925-airtable-automation-trigger-when-webhook-received
// Source: https://docs.discord.com/developers/resources/webhook#execute-webhook

/** Example payload of the source event, as documented. */
export const SOURCE_EXAMPLE = {
  "id": "rec123abc",
  "fields": {
    "Name": "John Doe",
    "Email": "john@example.com"
  },
  "createdTime": "2024-01-15T10:30:00.000Z"
}

export interface DocumentedEndpoint {
  method: string
  /** As documented; may contain placeholders such as {id}, :id, <id> or a region host like usX. */
  url: string
  response: unknown
}

/** Target endpoints the connector may call, in the documented order, with their documented responses. */
export const TARGET_ENDPOINTS: DocumentedEndpoint[] = [
  {
    "method": "POST",
    "url": "https://discord.com/api/webhooks/{webhook.id}/{webhook.token}",
    "response": {
      "id": "123456789012345678",
      "type": 1,
      "content": "New Airtable row: rec123abc - Name: John Doe, Email: john@example.com, Created: 2024-01-15T10:30:00.000Z",
      "channel_id": "987654321098765432",
      "author": {
        "username": "Webhook",
        "discriminator": "0001",
        "id": "987654321098765432",
        "avatar": null
      }
    }
  }
]

export interface RecordedCall {
  method: string
  url: string
  /** The request body exactly as sent (usually a JSON string). */
  body: string | undefined
  /** The body parsed as JSON, or undefined when it is not JSON. */
  json: unknown
  headers: Headers
}

/** The documented endpoint a request matches, placeholders and region subdomains included. */
export function findEndpoint(method: string, url: string): DocumentedEndpoint | undefined {
  return TARGET_ENDPOINTS.find((endpoint) => endpoint.method === method.toUpperCase() && urlMatches(endpoint.url, url))
}

/**
 * A fake fetch that answers every documented endpoint with its documented response and
 * rejects anything else. Use it in the contract test:
 *
 *   const { fetch, calls } = contractFetch()
 *   await handle(SOURCE_EXAMPLE as MyInput, { ...config, fetch })
 *   expect(calls.length).toBeGreaterThan(0)
 */
export function contractFetch(): { fetch: typeof fetch; calls: RecordedCall[] } {
  return fakeFetch((request) => {
    const endpoint = findEndpoint(request.method, request.url)
    if (!endpoint) throw new Error(`contract: ${request.method} ${request.url} is not a documented endpoint`)
    return jsonResponse(endpoint.response)
  })
}

/**
 * A correctly typed fake fetch for every other test. The handler receives the recorded
 * request: { method, url, body (string as sent), json (parsed body), headers (Headers) }.
 *
 *   const { fetch, calls } = fakeFetch((req) => req.url.endsWith('/deals') ? jsonResponse({ id: 1 }, 201) : jsonResponse({}, 404))
 */
export function fakeFetch(
  handler: (request: RecordedCall) => Response | Promise<Response>,
): { fetch: typeof fetch; calls: RecordedCall[] } {
  const calls: RecordedCall[] = []
  const fake = async (input: string | URL | Request, init: RequestInit = {}): Promise<Response> => {
    const url = input instanceof Request ? input.url : String(input)
    const method = (init.method ?? (input instanceof Request ? input.method : 'GET')).toUpperCase()
    const body = typeof init.body === 'string' ? init.body : init.body == null ? undefined : String(init.body)
    const call: RecordedCall = { method, url, body, json: parseJson(body), headers: new Headers(init.headers) }
    calls.push(call)
    return handler(call)
  }
  return { fetch: fake as typeof fetch, calls }
}

const STATUS_TEXT: Record<number, string> = {
  200: 'OK', 201: 'Created', 202: 'Accepted', 204: 'No Content',
  400: 'Bad Request', 401: 'Unauthorized', 403: 'Forbidden', 404: 'Not Found', 409: 'Conflict',
  422: 'Unprocessable Entity', 429: 'Too Many Requests',
  500: 'Internal Server Error', 502: 'Bad Gateway', 503: 'Service Unavailable',
}

/** A JSON Response with the standard status text, e.g. jsonResponse({ error: 'nope' }, 401) -> "401 Unauthorized". */
export function jsonResponse(body: unknown, status = 200): Response {
  const init = { status, statusText: STATUS_TEXT[status] ?? '', headers: { 'Content-Type': 'application/json' } }
  return new Response(status === 204 ? null : JSON.stringify(body), init)
}

function parseJson(raw: string | undefined): unknown {
  if (raw === undefined) return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

function urlMatches(template: string, actual: string): boolean {
  const t = splitUrl(template)
  const a = splitUrl(actual)
  if (!t || !a) return false
  const tHost = t.host.split('.')
  const aHost = a.host.split('.')
  if (tHost.slice(-2).join('.') !== aHost.slice(-2).join('.')) return false
  const tPath = t.path.replace(/\/+$/, '').split('/')
  const aPath = a.path.replace(/\/+$/, '').split('/')
  if (tPath.length !== aPath.length) return false
  return tPath.every((segment, i) => isPlaceholder(segment) || segment === aPath[i])
}

function splitUrl(url: string): { host: string; path: string } | null {
  const match = url.match(/^https?:\/\/([^/?#]+)([^?#]*)/i)
  return match ? { host: (match[1] ?? '').toLowerCase(), path: match[2] || '/' } : null
}

function isPlaceholder(segment: string): boolean {
  return /^\{[^}]+\}$|^:[A-Za-z_]\w*$|^<[^>]+>$/.test(segment)
}

