  discordChannelId: string
}

function buildDiscordWebhookUrl(config: ConnectorConfig): string {
  if (config.discordWebhookUrl) {
    return config.discordWebhookUrl
  }
  if (config.discordWebhookId && config.discordWebhookToken) {
    return `https://discord.com/api/webhooks/${config.discordWebhookId}/${config.discordWebhookToken}`
  }
