export async function handle(payload: unknown, config: ConnectorConfig): Promise<HandleResult> {
  validatePayload(payload)
  const airtablePayload = payload as AirtableWebhookPayload

  const content = formatMessageContent(airtablePayload)
  if (content.length > 2000) {
    throw new Error(`Message content exceeds Discord's 2000 character limit (got ${content.length})`)
  }

  const webhookUrl = buildDiscordWebhookUrl(config)
  const fetchImpl = config.fetch ?? fetch

  const response = await fetchImpl(webhookUrl, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
